new=r'''def irc_client(s):
    c=db(); token=None; nick=None; registered=False; joined={}
    s.settimeout(0.25); buf=b''
    def send(line):
        try:s.sendall((line+'\r\n').encode())
        except:pass
    def emit_new(cid):
        last=joined.get(cid,0)
        for e in c.execute("SELECT * FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id",(cid,last)).fetchall():
            joined[cid]=e['event_id']
            if e['type'] not in ('message.created','message.reply'): continue
            try: mid=json.loads(e['payload']).get('message')
            except: continue
            m=c.execute('SELECT m.*,u.username FROM messages m JOIN users u ON u.id=m.author_id WHERE m.id=?',(mid,)).fetchone()
            if not m: continue
            ch=c.execute('SELECT ch.*,w.slug FROM channels ch JOIN workspaces w ON w.id=ch.workspace_id WHERE ch.id=?',(cid,)).fetchone()
            if m['author_id']==c.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone()[0]: continue
            send(f":{m['username']}!{m['username']}@huddle PRIVMSG #{ch['slug']}/{ch['name']} :{m['body']}")
    try:
        while True:
            try:
                d=s.recv(4096)
                if not d: break
                buf+=d
            except socket.timeout:
                for cid in list(joined): emit_new(cid)
                continue
            while b'\r\n' in buf:
                line,buf=buf.split(b'\r\n',1); text=line.decode(errors='ignore')
                z=text.split(); cmd=z[0].upper() if z else ''
                if cmd=='PASS' and len(z)>1:
                    token=z[1]
                    if not c.execute('SELECT 1 FROM tokens WHERE token=?',(token,)).fetchone():
                        send('464 * :Password incorrect'); return
                elif cmd=='NICK' and len(z)>1:
                    nick=z[1]
                    if c.execute('SELECT 1 FROM users WHERE username=?',(nick,)).fetchone() and token:
                        own=c.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone()
                        other=c.execute('SELECT id FROM users WHERE username=?',(nick,)).fetchone()
                        if not own or own[0]!=other[0]: send(f':huddle 433 * {nick} :Nickname in use'); continue
                elif cmd=='USER' and token and nick and not registered:
                    registered=True
                    for n,msg in [('001','Welcome'),('002','Your host'),('003','Created'),('004','huddle'),('005','CHANTYPES=#')]:
                        send(f':huddle {n} {nick} :{msg}')
                    send(f':huddle 422 {nick} :No MOTD')
                elif cmd=='JOIN' and len(z)>1 and registered:
                    name=z[1]
                    if not name.startswith('#') or '/' not in name:
                        send(f':huddle 403 {nick} {name} :No such channel');continue
                    slug,chname=name[1:].split('/',1)
                    ch=c.execute('SELECT ch.*,w.slug FROM channels ch JOIN workspaces w ON w.id=ch.workspace_id WHERE w.slug=? AND ch.name=?',(slug,chname)).fetchone()
                    if not ch:
                        send(f':huddle 403 {nick} {name} :No such channel');continue
                    uid=c.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone()[0]
                    c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch['id'],uid));c.commit()
                    head=c.execute('SELECT COALESCE(MAX(event_id),0) FROM events WHERE channel_id=?',(ch['id'],)).fetchone()[0]
                    joined[ch['id']]=head
                    send(f':{nick}!{nick}@huddle JOIN :{name}')
                    names=' '.join(x['username'] for x in c.execute('SELECT u.username FROM users u JOIN channel_members cm ON cm.user_id=u.id WHERE cm.channel_id=?',(ch['id'],)))
                    send(f':huddle 353 {nick} = {name} :{names}')
                    send(f':huddle 366 {nick} {name} :End of NAMES list')
                elif cmd=='PRIVMSG' and len(z)>2 and registered:
                    target=z[1]; text=text.split(' :',1)[1] if ' :' in text else ' '.join(z[2:])
                    if target.startswith('#') and '/' in target[1:]:
                        slug,chname=target[1:].split('/',1)
                        ch=c.execute('SELECT ch.*,w.slug FROM channels ch JOIN workspaces w ON w.id=ch.workspace_id WHERE w.slug=? AND ch.name=?',(slug,chname)).fetchone()
                        if ch and text:
                            uid=c.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone()[0]
                            cur=c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(ch['id'],uid,text,None,now()));mid=cur.lastrowid
                            event(c,ch['id'],'message.created',{'message':mid});c.commit()
                elif cmd=='PING':
                    send('PONG '+(text.split(' ',1)[1] if ' ' in text else ''))
                elif cmd=='NAMES' and len(z)>1:
                    send(f':huddle 366 {nick} {z[1]} :End of NAMES list')
                elif cmd=='QUIT': return
            for cid in list(joined): emit_new(cid)
    finally:
        c.close();s.close()
'''
